script:
card({ name: "Secret Santa", icon: 'gift', permissions: ['sound'] });
const words = {
  join: "I'm in",
  leave: "Leave",
  in: "{p0} in so far",
  budget: "Spend up to, like 20",
  limit: "Spend up to {p0}",
  draw: "Draw names",
  needThree: "Three people at least",
  drawn: "Names are drawn",
  yours: "You're buying for",
  notIn: "You weren't in this draw",
  by: "Drawn by {p0}",
  again: "Start over",
  closed: "Names are already drawn",
  full: "Forty people at most",
  onlySender: "Only the person who sent the card can do that",
  waitDraw: "Names are drawn by whoever sent the card",
  everyone: "Everyone knows who they're buying for. Only they see it.",
};

// Whoever sent the card draws the names and can start over. Each person
// sees only who they're buying for.
function init() {
  return { people: {}, budget: '', pairs: null, by: '' };
}

on.join = (s, args, ctx) => {
  if (s.pairs) throw words.closed;
  if (Object.keys(s.people).length >= 40) throw words.full;
  s.people[ctx.author] = ctx.authorName;
};

on.leave = (s, args, ctx) => {
  if (s.pairs) throw words.closed;
  delete s.people[ctx.author];
};

on.budget = (s, args) => {
  s.budget = String(args.value || '').trim().slice(0, 20);
};

// Shuffle everyone into a circle: each buys for the next, so nobody gets
// themselves and nobody is left out.
on.draw = (s, args, ctx) => {
  if (ctx.author !== ctx.sender) throw words.onlySender;
  if (s.pairs) throw words.closed;
  const ids = Object.keys(s.people);
  if (ids.length < 3) throw words.needThree;
  for (let i = ids.length - 1; i > 0; i--) {
    const j = Math.floor(ctx.random() * (i + 1));
    const t = ids[i];
    ids[i] = ids[j];
    ids[j] = t;
  }
  s.pairs = {};
  ids.forEach((id, i) => {
    s.pairs[id] = ids[(i + 1) % ids.length];
  });
  s.by = ctx.authorName;
  ctx.sound('win');
};

on.again = (s, args, ctx) => {
  if (ctx.author !== ctx.sender) throw words.onlySender;
  return init();
};

function view(s, me) {
  const names = Object.values(s.people);
  const budget = s.budget && badge(words.limit.replace('{p0}', s.budget), { tone: 'accent' });
  if (s.pairs) {
    const to = s.pairs[me.id];
    return column([
      text(words.drawn, { tone: 'muted', align: 'center' }),
      to ? text(words.yours, { align: 'center' }) : text(words.notIn, { tone: 'muted', align: 'center' }),
      to && text('🎁 ' + s.people[to], { size: 'huge', bold: true, align: 'center', tone: 'accent' }),
      budget,
      text(words.by.replace('{p0}', s.by), { size: 'small', tone: 'muted', align: 'center' }),
      me.isSender && text(words.everyone, { size: 'small', tone: 'muted', align: 'center' }),
      me.isSender && text(names.join(', '), { size: 'small', tone: 'muted', align: 'center' }),
      me.isSender && button(words.again, 'again', null, { tone: 'muted', align: 'center' }),
    ]);
  }
  const joined = !!s.people[me.id];
  return column([
    text(words.in.replace('{p0}', names.length), { bold: true }),
    names.length > 0 && text(names.join(', '), { tone: 'muted' }),
    budget,
    input('budget', words.budget, 'budget'),
    row([
      button(joined ? words.leave : words.join, joined ? 'leave' : 'join', null, { tone: joined ? 'muted' : 'accent' }),
      me.isSender && names.length >= 3 && button('🎲 ' + words.draw, 'draw', null, { tone: 'success' }),
    ], { align: 'center' }),
    names.length < 3
      ? text(words.needThree, { size: 'small', tone: 'muted', align: 'center' })
      : !me.isSender && text(words.waitDraw, { size: 'small', tone: 'muted', align: 'center' }),
  ]);
}
